sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  var data = api.data.issue_side_panel.output;
  if(data && data.details){
    var controls = data.details.control.length;
    var risks = data.details.risk.length;
    var policies = data.details.policy.length;
    var authDocs = data.details.authorityDocument.length;
    var engagements = data.details.engagement.length;
    var regTasks = data.details.regTask.length;
    var remTasks = data.details.remediationTask.length;
    var riskEvents = data.details.riskEvent.length;

    if(controls == 0 && risks == 0 && policies == 0 && authDocs == 0 && engagements == 0 && regTasks == 0 && remTasks == 0 && riskEvents == 0){
      return false;
    }
    return true;
  }
	return true;
}
